<?php
declare(strict_types=1);namespace Atlas\Platform\PatientResources\Services;use Atlas\Platform\PatientResources\Domain\PatientResourcePolicy;use Atlas\Platform\PatientResources\Domain\PatientResourceVariant;use Atlas\Platform\PatientResources\Repositories\PatientResourceAccessRepository;use Atlas\Platform\PatientResources\Repositories\VariantRepository;use InvalidArgumentException;final class PatientResourceVariantService{public function __construct(private VariantRepository $variants,private PatientResourceAccessRepository $access,private PatientResourcePolicy $policy){}public function save(string $org,string $version,array $input,string $key,int $user,string $name=''):?PatientResourceVariant{if($org===''||$user<=0){return null;}if(preg_match('/^[A-Za-z0-9._:-]{8,128}$/',$key)!==1){throw new InvalidArgumentException('A valid idempotency key is required.');}if(!$this->access->isPublishedPatientEducationVersion($version,$org)){return null;}return $this->variants->save($org,$version,$this->policy->normalize($input),$key,$user,$this->name($name));}public function update(string$org,string$id,array$input,int$user,string$name=''):bool{if($org===''||$id===''||$user<=0){return false;}return$this->variants->updateCustomizations($id,$org,$this->policy->normalize($input),$user,$this->name($name));}private function name(string$name):string{return substr(trim($name),0,255);}}
